/**
 * Credential login, registration and password reset. No third-party provider.
 *
 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
 *
 * Note: `TaskflowEventMap` has no authentication event and the type is part of
 * the frozen contract, so the declared `emit` is not reachable from here.
 * Registration still publishes `member.joined` — through
 * `OrganizationService.createOrganization`, which owns that membership row.
 */
import {
  hashPassword,
  hashToken,
  randomToken,
  verifyPassword,
} from "@/lib/hash";
import { consumeRateLimit } from "@/lib/rate-limit";
import { slugify } from "@/lib/slug";
import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { createOrganization } from "./organization-service";
import { renderEmail, sendEmail } from "./email-service";
import { createSessionToken } from "./session-service";
import type {
  LoginInput,
  PasswordResetConfirmInput,
  PasswordResetRequestInput,
  RegisterInput,
} from "@/schemas/auth";
import type { OrgId, SessionId } from "@/types/common";
import type { User } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Buckets guarding the unauthenticated endpoints. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * every unauthenticated attempt is billed to this sentinel bucket.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** How long a password-reset link stays usable. */
const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * Registration creates the user and their first workspace in one step — a
 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new Error("An account with that email already exists");
  }

  const user = await userRepo.insertUser({
    email: input.email,
    name: input.name,
    passwordHash: await hashPassword(input.password),
  });

  const org = await createOrganization(user.id, {
    name: `${input.name}'s workspace`,
    slug: slugify(input.name) || "workspace",
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

/**
 * Credential login. The rate limit is charged before the password is checked,
 * so a brute-force run is throttled whether or not it guesses correctly, and
 * both failure modes return the same message.
 */
export async function login(
  input: LoginInput,
): Promise<{ user: User; token: string }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
  if (!verdict.allowed) {
    throw new Error("Too many sign-in attempts; try again shortly");
  }

  const user = await userRepo.findUserByEmail(input.email);
  if (!user) throw new Error("Those credentials did not match");

  const storedHash = await userRepo.findPasswordHash(user.id);
  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
    throw new Error("Those credentials did not match");
  }

  const { token } = await createSessionToken(user.id);

  return { user, token };
}

export async function logout(sessionId: SessionId): Promise<void> {
  await sessionRepo.revokeSession(sessionId);
}

/**
 * Always resolves, whether or not the address is known — telling an anonymous
 * caller which emails have accounts is an enumeration oracle. Only the token's
 * hash is stored; the raw value exists solely inside the email that carries it.
 */
export async function requestPasswordReset(
  input: PasswordResetRequestInput,
): Promise<void> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
  if (!verdict.allowed) return;

  const user = await userRepo.findUserByEmail(input.email);
  if (!user) return;

  const token = randomToken(32);
  await resetTokenRepo.issueResetToken(
    user.id,
    hashToken(token),
    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
  );

  const message = await renderEmail("password-reset", {
    recipientName: user.name,
    token,
    expiresInMinutes: RESET_TTL_MS / 60_000,
  });

  await sendEmail({ to: user.email, ...message });
}

/**
 * Consumes a reset token and rewrites the password hash. The token is marked
 * used before the new hash is written, so a replay of the same link cannot
 * overwrite a password the user has since changed again.
 */
export async function confirmPasswordReset(
  input: PasswordResetConfirmInput,
): Promise<User> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
  if (!verdict.allowed) {
    throw new Error("Too many reset attempts; try again shortly");
  }

  const stored = await resetTokenRepo.findLiveResetToken(
    hashToken(input.token),
  );
  if (!stored) throw new Error("That reset link is no longer valid");

  await resetTokenRepo.consumeResetToken(stored.id);
  await userRepo.updatePasswordHash(
    stored.userId,
    await hashPassword(input.password),
  );

  const user = await userRepo.findUserById(stored.userId);
  if (!user) throw new Error("That reset link is no longer valid");

  return user;
}
/**
 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
 *
 * Must call (do not reimplement): assertOrgScope
 */
import { hashToken, randomToken } from "@/lib/hash";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import { toIsoTimestamp } from "@/types/common";
import type { SwitchOrgInput } from "@/schemas/session";
import type { IsoTimestamp, UserId } from "@/types/common";
import type { Actor, SessionPrincipal } from "@/types/member";

/** How long a freshly issued session cookie stays valid. */
const SESSION_TTL_DAYS = 30;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login.
 */
export async function createSessionToken(
  userId: UserId,
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
  );

  await sessionRepo.createSession(userId, hashToken(token), expiresAt);

  return { token, expiresAt };
}

export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

/**
 * The bridge between "who is logged in" and "what may they do here": given a
 * principal and the org slug in the URL, produce the `Actor` every service
 * method takes, or `null` when the user is not a member of that org.
 *
 * The `assertOrgScope` call at the end looks redundant — the actor was just
 * built from that org — but it is the invariant this whole layer exists to
 * uphold, and it catches a mis-wired membership lookup immediately.
 */
export async function resolveActorForOrg(
  principal: SessionPrincipal,
  orgSlug: string,
): Promise<Actor | null> {
  const org = await orgRepo.findOrgBySlug(orgSlug);
  if (!org) return null;

  const member = await memberRepo.findMember(org.id, principal.userId);
  if (!member || member.status !== "active") return null;

  const actor: Actor = {
    userId: principal.userId,
    orgId: org.id,
    role: member.role,
  };

  assertOrgScope(actor, org.id);

  await memberRepo.touchLastSeen(
    org.id,
    principal.userId,
    toIsoTimestamp(new Date()),
  );

  return actor;
}

/**
 * Switches the org a session defaults to. Membership is re-checked here so a
 * removed member cannot pin their cookie to an org they left.
 *
 * `SessionPrincipal` carries no session id, so the write to `sessions.
 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
 * Action, which still holds the cookie. This method owns the authorization
 * half of the switch.
 */
export async function switchActiveOrg(
  principal: SessionPrincipal,
  input: SwitchOrgInput,
): Promise<void> {
  const member = await memberRepo.findMember(input.orgId, principal.userId);
  if (!member || member.status !== "active") {
    throw new Error("You are not a member of that organization");
  }

  const orgs = await orgRepo.listOrgsForUser(principal.userId);
  const target = orgs.find((org) => org.id === input.orgId);
  if (!target) throw new Error("You are not a member of that organization");

  assertOrgScope(
    { userId: principal.userId, orgId: input.orgId, role: member.role },
    target.id,
  );
}

/**
 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
 * exposes no session id, so the sweep is what actually clears the row, and the
 * cookie is dropped by the caller either way.
 */
export async function destroySession(token: string): Promise<void> {
  const principal = await resolveSession(token);
  if (!principal) return;

  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
}
/**
 * Receives third-party callbacks validated with `inboundWebhookSchema`.
 *
 * Owner D. The receiver is deliberately dumb: it validates the envelope, charges
 * a rate limit and hands the payload to the event bus. Anything that needs to
 * happen as a result is a subscriber's job, so a slow handler cannot make the
 * sender time out and retry.
 *
 * Must call (do not reimplement): inboundWebhookSchema, consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { emit } from "@/lib/event-bus";
import { consumeRateLimit } from "@/lib/rate-limit";
import { inboundWebhookSchema } from "@/schemas/webhook";
import { toIsoTimestamp } from "@/types/common";

export const dynamic = "force-dynamic";

const INBOUND_BUCKET = "webhook:inbound";

export async function POST(request: Request): Promise<Response> {
  try {
    // The sender is not a tenant, so the bucket is the shared anonymous one.
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, INBOUND_BUCKET);
    if (!verdict.allowed) {
      return failure("rate_limited", "Too many inbound callbacks.");
    }

    const body: unknown = await request.json();
    const parsed = inboundWebhookSchema.safeParse(body);
    if (!parsed.success) {
      return failure("validation_failed", "Unrecognised callback envelope.");
    }

    await emit("webhook.delivery_requested", {
      orgId: ANONYMOUS_ORG_ID,
      actorId: null,
      occurredAt: toIsoTimestamp(parsed.data.occurredAt),
      eventType: `inbound.${parsed.data.source}`,
      payload: parsed.data.payload,
    });

    // 202: the callback is accepted, not yet acted on.
    return Response.json({ accepted: true, eventId: parsed.data.eventId }, { status: 202 });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Sends a signed test payload to one endpoint.
 *
 * Owner D. The point of the route is to prove the *signature* round-trips, so
 * it returns the signature it computed alongside the payload — a customer can
 * verify their own check against a known-good pair without waiting for a real
 * event.
 *
 * Must call (do not reimplement): can, signPayload
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { webhookIdSchema } from "@/schemas/common";
import { listWebhooks, signPayload } from "@/server/services/webhook-service";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ endpointId: string }> };

export async function POST(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { endpointId } = await context.params;
    const parsedId = webhookIdSchema.safeParse(endpointId);
    if (!parsedId.success) {
      return failure("validation_failed", "Malformed endpoint id.");
    }

    const actor = await getActor(orgSlug);

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: actor.orgId,
      webhookId: parsedId.data,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot manage webhooks here.");
    }

    // Listing is org-scoped, so an endpoint id from another tenant simply is
    // not in the result and the route reports it as missing.
    const endpoints = await listWebhooks(actor, actor.orgId);
    const endpoint = endpoints.find((row) => row.id === parsedId.data);
    if (endpoint === undefined) {
      return failure("not_found", "No such endpoint in this organization.");
    }

    const payload = JSON.stringify({
      eventType: "webhook.test",
      orgId: actor.orgId,
      endpointId: endpoint.id,
      sentAt: new Date().toISOString(),
    });

    return Response.json({
      delivered: endpoint.enabled,
      url: endpoint.url,
      signature: signPayload(endpoint.secret, payload),
      payload,
    });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Fetch/patch one issue over JSON.
 *
 * Owner D. The tenant check is explicit here rather than implied: the route
 * takes an `issueId` straight off the URL, so `assertOrgScope()` against the
 * fetched row is what stops one organization reading another's issue by id.
 *
 * Must call (do not reimplement): can, assertOrgScope
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { issueIdSchema } from "@/schemas/common";
import { updateIssueSchema } from "@/schemas/issue";
import { getIssue, updateIssue } from "@/server/services/issue-service";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ issueId: string }> };

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const parsedId = issueIdSchema.safeParse(issueId);
    if (!parsedId.success) {
      return failure("validation_failed", "Malformed issue id.");
    }

    const actor = await getActor(orgSlug);
    const found = await getIssue(actor, actor.orgId, parsedId.data);
    assertOrgScope(actor, found.issue.orgId);

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: found.issue.orgId,
      projectId: found.issue.projectId,
      issueId: found.issue.id,
      authorId: found.issue.authorId,
      assigneeId: found.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot read this issue.");
    }

    return Response.json(found);
  } catch (error) {
    return errorResponse(error);
  }
}

export async function PATCH(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const actor = await getActor(orgSlug);

    const body: unknown = await request.json();
    const parsed = updateIssueSchema.safeParse({
      ...(typeof body === "object" && body !== null ? body : {}),
      orgId: actor.orgId,
      issueId,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad issue patch.");
    }

    const current = await getIssue(actor, actor.orgId, parsed.data.issueId);
    assertOrgScope(actor, current.issue.orgId);

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: current.issue.orgId,
      projectId: current.issue.projectId,
      issueId: current.issue.id,
      authorId: current.issue.authorId,
      assigneeId: current.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot update this issue.");
    }

    const updated = await updateIssue(actor, parsed.data);
    return Response.json(updated);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Shared JSON helpers for the route handlers.
 *
 * Owner D. Every handler under `src/app/api` returns the same envelope as the
 * Server Actions — `{ error: AppErrorShape }` on failure — so a client can use
 * one parser for both. The status code comes from `HTTP_STATUS_BY_CODE`, which
 * is the single mapping from domain error code to HTTP.
 */

import { HTTP_STATUS_BY_CODE, toAppError } from "@/lib/errors";
import type { AppErrorShape, ApiErrorBody } from "@/types/api";

/** Turns any thrown value into the JSON error envelope with the right status. */
export function errorResponse(error: unknown): Response {
  const shape: AppErrorShape = toAppError(error);
  const body: ApiErrorBody = { error: shape };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[shape.code] });
}

/** Builds the envelope for a failure the handler detected itself. */
export function failure(
  code: AppErrorShape["code"],
  message: string,
): Response {
  const body: ApiErrorBody = { error: { code, message } };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[code] });
}

/**
 * Cron endpoints are protected by a shared secret rather than a session — they
 * are called by the platform scheduler, which has no cookie jar.
 */
export function assertCronSecret(request: Request): void {
  const expected = process.env.TASKFLOW_CRON_SECRET;
  if (expected === undefined || expected.length === 0) {
    // No secret configured means cron is disabled rather than wide open.
    throw new CronAuthError("Cron trigger is not configured.");
  }
  if (request.headers.get("x-taskflow-cron") !== expected) {
    throw new CronAuthError("Bad cron secret.");
  }
}

export class CronAuthError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message: string) {
    super(message);
    this.name = "CronAuthError";
  }
}

