import { createProjectSchema, type CreateProjectInput } from "@/schemas/project";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof createProjectSchema, Project>(
  createProjectSchema,
  async (raw, actor) => {
    const input = raw as CreateProjectInput;

    const allowed = can(actor, "project:create", {
      kind: "project",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      visibility: input.visibility,
      leadId: input.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:create");
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.projectsUsed >= limits.projects) {
      throw new PlanLimitError("projects", limits.projects, summary.usage.projectsUsed);
    }

    const project = await createProject(actor, input);
    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function createProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Restores an archived project.
 *
 * Owner D. There is no `restoreProjectSchema` in `src/schemas` because the
 * payload is nothing but the two ids, so the shape is composed here from the
 * shared branded-id primitives rather than added to the frozen schema layer.
 *
 * Must call (do not reimplement): can, restorePatch, getActor, toActionResult
 */

import { ActionNotFoundError, ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { restorePatch } from "@/lib/soft-delete";
import { orgIdSchema, projectIdSchema } from "@/schemas/common";
import { listProjects, restoreProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";
import { z } from "zod";

const restoreProjectSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
});

type RestoreProjectInput = z.infer<typeof restoreProjectSchema>;

const run = withAction<typeof restoreProjectSchema, Project>(
  restoreProjectSchema,
  async (raw, actor) => {
    const input = raw as RestoreProjectInput;

    const page = await listProjects(actor, {
      orgId: input.orgId,
      limit: 100,
      includeArchived: true,
    });
    const current = page.items.find((row) => row.project.id === input.projectId);
    if (current === undefined) {
      throw new ActionNotFoundError(`project ${input.projectId}`);
    }

    const allowed = can(actor, "project:archive", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: current.project.visibility,
      leadId: current.project.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:archive");
    }

    const project = await restoreProject(actor, input.orgId, input.projectId);

    // `restorePatch()` is the single definition of what "restored" looks like;
    // comparing against it catches a service that forgot to clear the column.
    const expected = restorePatch();
    if (project.archivedAt !== expected.archivedAt) {
      throw new ActionNotFoundError(`live project ${input.projectId}`);
    }

    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function restoreProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Archives a project and, optionally, its issues.
 *
 * Owner D. `archiveIssues` defaults to true: leaving live issues under an
 * archived project is the state that makes every "open issues" count wrong, so
 * opting out has to be deliberate.
 *
 * Must call (do not reimplement): archiveProjectSchema, can, assertNotArchived,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { archiveProjectSchema, type ArchiveProjectInput } from "@/schemas/project";
import {
  archiveProject,
  listProjects,
} from "@/server/services/project-service";
import { ActionNotFoundError } from "@/actions/_lib/action-errors";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof archiveProjectSchema, Project>(
  archiveProjectSchema,
  async (raw, actor) => {
    const input = raw as ArchiveProjectInput;

    const page = await listProjects(actor, {
      orgId: input.orgId,
      limit: 100,
      includeArchived: true,
    });
    const current = page.items.find((row) => row.project.id === input.projectId);
    if (current === undefined) {
      throw new ActionNotFoundError(`project ${input.projectId}`);
    }

    const allowed = can(actor, "project:archive", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: current.project.visibility,
      leadId: current.project.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:archive");
    }

    assertNotArchived("project", input.projectId, current.project);

    const project = await archiveProject(actor, input);
    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects", "issues"], cacheProfile: "minutes" },
);

export async function archiveProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Creates an issue after the per-project quota check.
 *
 * Owner D. The quota is read from `@/config/plan-limits` rather than hard-coded
 * here — the plan of the owning organization decides `issuesPerProject`.
 *
 * Must call (do not reimplement): createIssueSchema, can, getPlanLimits,
 * getActor, toActionResult
 */

import { withAction } from "@/actions/_lib/with-action";
import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { getPlanLimits } from "@/config/plan-limits";
import { issueTag, orgTag, projectTag, revalidateTagged, CACHE_PROFILES } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
import { createIssue, listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

const run = withAction<typeof createIssueSchema, Issue>(
  createIssueSchema,
  async (raw, actor) => {
    const input = raw as CreateIssueInput;

    const allowed = can(actor, "issue:create", {
      kind: "issue",
      orgId: input.orgId,
      projectId: input.projectId,
      issueId: "" as Issue["id"],
      authorId: actor.userId,
      assigneeId: input.assigneeId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:create");
    }

    await assertProjectHasRoom(actor, input);

    const issue = await createIssue(actor, input);

    revalidateTagged(
      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
      CACHE_PROFILES.minutes,
    );
    return issue;
  },
  { revalidate: ["issues"], cacheProfile: "minutes" },
);

/**
 * Counts the issues already living in the project and compares them with the
 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
 * which is why the count deliberately includes them.
 */
async function assertProjectHasRoom(
  actor: Actor,
  input: CreateIssueInput,
): Promise<void> {
  const summary = await getOrganizationSummary(actor, input.orgId);
  const limits = getPlanLimits(summary.organization.plan);

  const existing = await listIssues(actor, {
    orgId: input.orgId,
    projectId: input.projectId,
    limit: 1,
    includeArchived: true,
  });

  if (existing.total >= limits.issuesPerProject) {
    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
  }
}

export async function createIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}
"use server";

/**
 * Board drag-and-drop target; reconciles the optimistic update.
 *
 * Owner D. The client has already moved the card via `useOptimisticIssues`, so
 * the only thing that matters here is returning the authoritative row — the
 * hook reconciles against it and snaps the card back if the move was refused.
 * Dragging is only reachable when `kanban_board` is on, and the flag is
 * re-checked server-side because the client copy is only a snapshot.
 *
 * Must call (do not reimplement): moveIssueSchema, can, isEnabled, getActor,
 * toActionResult
 */

import {
  FeatureUnavailableError,
  ForbiddenActionError,
} from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, projectTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { moveIssueSchema, type MoveIssueInput } from "@/schemas/issue";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { moveIssue } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";

const run = withAction<typeof moveIssueSchema, Issue>(
  moveIssueSchema,
  async (raw, actor) => {
    const input = raw as MoveIssueInput;

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: input.issueId,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:update");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    if (!isEnabled("kanban_board", buildFlagContext(actor, organization))) {
      throw new FeatureUnavailableError("kanban_board");
    }

    const issue = await moveIssue(actor, input);
    revalidateTagged(
      [issueTag(issue.id), projectTag(issue.projectId)],
      CACHE_PROFILES.seconds,
    );
    return issue;
  },
  { revalidate: ["board"], cacheProfile: "seconds" },
);

export async function moveIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}
"use server";

/**
 * Changes plan; refuses a downgrade that would breach a current quota.
 *
 * Owner D. The interesting case is the *downgrade*: the target plan's limits
 * are compared against today's usage before the switch, so an org on growth
 * with 40 seats cannot silently drop to starter and strand 37 people.
 *
 * Must call (do not reimplement): changePlanSchema, can, getPlanLimits,
 * wouldExceedLimit, getActor, toActionResult
 */

import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { changePlanSchema, type ChangePlanInput } from "@/schemas/billing";
import { changePlan } from "@/server/services/billing-service";
import { getUsage } from "@/server/services/usage-service";
import type { ActionResult } from "@/types/api";
import type { LimitedResource, Subscription } from "@/types/billing";
import type { Actor } from "@/types/member";

const run = withAction<typeof changePlanSchema, Subscription>(
  changePlanSchema,
  async (raw, actor) => {
    const input = raw as ChangePlanInput;

    if (!can(actor, "org:manage_billing", { kind: "billing", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:manage_billing");
    }

    await assertPlanFitsCurrentUsage(actor, input);

    const subscription = await changePlan(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return subscription;
  },
  { revalidate: ["billing"], cacheProfile: "hours" },
);

/**
 * Compares live usage against the *target* plan. `wouldExceedLimit` is called
 * with a requested delta of zero: we are not consuming anything, only asking
 * whether what is already in use still fits.
 */
async function assertPlanFitsCurrentUsage(
  actor: Actor,
  input: ChangePlanInput,
): Promise<void> {
  const usage = await getUsage(actor, input.orgId);
  const limits = getPlanLimits(input.plan);

  const consumption: ReadonlyArray<readonly [LimitedResource, number]> = [
    ["seats", usage.seatsUsed],
    ["projects", usage.projectsUsed],
    ["storageMb", usage.storageMbUsed],
  ];

  for (const [resource, used] of consumption) {
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new PlanLimitError(resource, limits[resource], used);
    }
  }
}

export async function changePlanAction(raw: unknown): Promise<ActionResult<Subscription>> {
  return run(raw);
}
"use server";

/**
 * Toggles an org-level feature flag override.
 *
 * Owner D. An override can only *turn on* a flag whose definition is
 * `overridable`; `isEnabled()` is consulted first so that toggling a flag which
 * is already on for structural reasons (plan or rollout percentage) is a no-op
 * rather than a confusing write.
 *
 * Must call (do not reimplement): toggleFeatureFlagSchema, can, isEnabled,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import {
  toggleFeatureFlagSchema,
  type ToggleFeatureFlagInput,
} from "@/schemas/feature-flag";
import {
  buildFlagContext,
  toggleFlag,
} from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";

const run = withAction<typeof toggleFeatureFlagSchema, Organization>(
  toggleFeatureFlagSchema,
  async (raw, actor) => {
    const input = raw as ToggleFeatureFlagInput;

    if (!can(actor, "org:manage_flags", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:manage_flags");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    const context = buildFlagContext(actor, organization);
    if (isEnabled(input.flag, context) === input.enabled) {
      return organization;
    }

    const updated = await toggleFlag(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return updated;
  },
  { revalidate: ["flags"], cacheProfile: "minutes" },
);

export async function toggleFeatureFlagAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}
"use server";

/**
 * Registers a webhook endpoint; plan and flag gated.
 *
 * Owner D. Two independent gates: the `webhooks` feature flag (which is itself
 * plan-derived) and the numeric `webhooks` quota. Both are checked because a
 * flag can be force-enabled through an org override while the quota still
 * applies.
 *
 * Must call (do not reimplement): createWebhookSchema, can, isEnabled,
 * getPlanLimits, getActor, toActionResult
 */

import {
  FeatureUnavailableError,
  ForbiddenActionError,
  PlanLimitError,
} from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { createWebhookSchema, type CreateWebhookInput } from "@/schemas/webhook";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createWebhook, listWebhooks } from "@/server/services/webhook-service";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof createWebhookSchema, WebhookEndpointRow>(
  createWebhookSchema,
  async (raw, actor) => {
    const input = raw as CreateWebhookInput;

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: input.orgId,
      webhookId: null,
    });
    if (!allowed) {
      throw new ForbiddenActionError("webhook:manage");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    if (!isEnabled("webhooks", buildFlagContext(actor, organization))) {
      throw new FeatureUnavailableError("webhooks");
    }

    const limits = getPlanLimits(organization.plan);
    const existing = await listWebhooks(actor, input.orgId);
    if (existing.length >= limits.webhooks) {
