/**
 * The read-only lock a workspace falls under while its subscription is not in
 * good standing.
 *
 * Two things live here and nothing else: the pure rule that turns a stored
 * subscription into a lock reason, and the error a refused write throws. The
 * rule takes no database handle on purpose — `BillingService` reads the row,
 * this module only judges it — so it can be evaluated anywhere, including in
 * `toAppError()` without dragging the server layer into `@/lib`.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

const LOCK_MESSAGES: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due:
    "This workspace is read-only because its last payment failed. Update billing to continue.",
  canceled:
    "This workspace is read-only because its subscription was canceled. Choose a plan to continue.",
  trial_ended:
    "This workspace is read-only because its trial has ended. Choose a plan to continue.",
};

/** The sentence shown to a member whose write was refused, and by the banner. */
export function lockMessageFor(reason: WorkspaceLockReason): string {
  return LOCK_MESSAGES[reason];
}

/** Thrown for every member write into a locked workspace. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(lockMessageFor(reason));
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Why the workspace owning `subscription` is locked at `now`, or `null` when
 * it is writable.
 *
 * - no subscription row, or an `active` one: writable;
 * - `past_due`: locked;
 * - `trialing`: locked once the period end has been reached;
 * - `canceled`: locked once the cancellation date has been reached — a
 *   cancellation scheduled for later leaves the workspace writable until
 *   then, and one with no date at all counts as canceled already.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null || subscription === undefined) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now)
        ? "trial_ended"
        : null;
    case "canceled":
      if (subscription.cancelAt === null || subscription.cancelAt === undefined) {
        return "canceled";
      }
      return hasReached(subscription.cancelAt, now) ? "canceled" : null;
    default:
      return null;
  }
}

/** True from the instant `stamp` is reached: at it, or any time after. */
function hasReached(stamp: string, now: Date): boolean {
  return now.getTime() >= new Date(stamp).getTime();
}
EOF

