/**
 * Why the workspace is read-only at `now`, or `null` when it is writable.
 * Always read from the stored subscription row — never from the denormalised
 * `organizations.plan` / `trialEndsAt` columns and never cached — so a plan
 * change or a webhook-driven status flip takes effect on the very next write.
 */
export async function getWorkspaceLockReason(
  orgId: OrgId,
  now: Date = new Date(),
): Promise<WorkspaceLockReason | null> {
  return lockReasonFor(await subscriptionRepo.findSubscription(orgId), now);
}

/**
 * The write gate. Every member-initiated mutation outside billing itself calls
 * this immediately after its permission check, so an unauthorised caller is
 * still refused for the reason they always were and only a caller who would
 * otherwise have written sees the lock.
 *
 * Deliberately *not* called by billing (the way out of the lock), by
 * organization deletion, by a member's own notification housekeeping, or by
 * anything Taskflow does on its own behalf (event subscribers and jobs).
 */
export async function assertWorkspaceWritable(
  orgId: OrgId,
  now: Date = new Date(),
): Promise<void> {
  const reason = await getWorkspaceLockReason(orgId, now);
  if (reason !== null) {
    throw new WorkspaceLockedError(orgId, reason);
  }
}
