cat > tests/lib/billing-lock.test.ts <<'EOF'
/** The pure workspace-lock rule: which stored subscriptions are read-only, and from when. */
import { describe, expect, it } from "vitest";
import { WorkspaceLockedError, lockReasonFor } from "@/lib/billing-lock";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp, SubscriptionId } from "@/types/common";
import { ORG_A } from "../helpers/factories";

const PERIOD_END = "2026-06-15T00:00:00.000Z" as IsoTimestamp;
const AT_END = new Date(PERIOD_END);
const JUST_BEFORE = new Date(AT_END.getTime() - 1);
const JUST_AFTER = new Date(AT_END.getTime() + 1);

function makeSubscription(overrides: Partial<Subscription> = {}): Subscription {
  return {
    id: "01HZZZSUBSUBSUBSUBSUBSUBSU" as SubscriptionId,
    orgId: ORG_A,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 5,
    currentPeriodStart: "2026-06-01T00:00:00.000Z" as IsoTimestamp,
    currentPeriodEnd: PERIOD_END,
    cancelAt: null,
    createdAt: "2026-06-01T00:00:00.000Z" as IsoTimestamp,
    updatedAt: "2026-06-01T00:00:00.000Z" as IsoTimestamp,
    ...overrides,
  };
}

describe("lib/billing-lock", () => {
  it("treats a workspace with no subscription row as writable", () => {
    expect(lockReasonFor(null, AT_END)).toBeNull();
  });

  it("treats an active subscription as writable, even past its period end", () => {
    expect(lockReasonFor(makeSubscription(), JUST_AFTER)).toBeNull();
    expect(
      lockReasonFor(makeSubscription({ cancelAt: PERIOD_END }), JUST_AFTER),
    ).toBeNull();
  });

  it("locks a past-due subscription regardless of dates", () => {
    const subscription = makeSubscription({ status: "past_due" });
    expect(lockReasonFor(subscription, JUST_BEFORE)).toBe("past_due");
    expect(lockReasonFor(subscription, JUST_AFTER)).toBe("past_due");
  });

  it("locks a trial from the moment its period end is reached", () => {
    const subscription = makeSubscription({ status: "trialing" });
    expect(lockReasonFor(subscription, JUST_BEFORE)).toBeNull();
    expect(lockReasonFor(subscription, AT_END)).toBe("trial_ended");
    expect(lockReasonFor(subscription, JUST_AFTER)).toBe("trial_ended");
  });

  it("keeps a cancellation scheduled for later writable until its date", () => {
    const subscription = makeSubscription({
      status: "canceled",
      cancelAt: PERIOD_END,
    });
    expect(lockReasonFor(subscription, JUST_BEFORE)).toBeNull();
    expect(lockReasonFor(subscription, AT_END)).toBe("canceled");
    expect(lockReasonFor(subscription, JUST_AFTER)).toBe("canceled");
  });

  it("counts a canceled subscription with no cancellation date as canceled now", () => {
    const subscription = makeSubscription({ status: "canceled", cancelAt: null });
    expect(lockReasonFor(subscription, JUST_BEFORE)).toBe("canceled");
  });

  it("defaults `now` to the current time", () => {
    const longAgo = "2000-01-01T00:00:00.000Z" as IsoTimestamp;
    const farAhead = "2999-01-01T00:00:00.000Z" as IsoTimestamp;

    expect(
      lockReasonFor(makeSubscription({ status: "trialing", currentPeriodEnd: longAgo })),
    ).toBe("trial_ended");
    expect(
      lockReasonFor(makeSubscription({ status: "trialing", currentPeriodEnd: farAhead })),
    ).toBeNull();
  });

  it("carries the org, the reason and the plan-limit code on the error", () => {
    const error = new WorkspaceLockedError(ORG_A, "trial_ended");

    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(error.reason).toBe("trial_ended");
  });
});
EOF
