    const subscription = makeSubscription({ status: "trialing" });
    expect(lockReasonFor(subscription, JUST_BEFORE)).toBeNull();
    expect(lockReasonFor(subscription, AT_END)).toBe("trial_ended");
    expect(lockReasonFor(subscription, JUST_AFTER)).toBe("trial_ended");
  });

  it("keeps a cancellation scheduled for later writable until its date", () => {
    const subscription = makeSubscription({
      status: "canceled",
      cancelAt: PERIOD_END,
    });
    expect(lockReasonFor(subscription, JUST_BEFORE)).toBeNull();
    expect(lockReasonFor(subscription, AT_END)).toBe("canceled");
    expect(lockReasonFor(subscription, JUST_AFTER)).toBe("canceled");
  });

  it("counts a canceled subscription with no cancellation date as canceled now", () => {
    const subscription = makeSubscription({ status: "canceled", cancelAt: null });
    expect(lockReasonFor(subscription, JUST_BEFORE)).toBe("canceled");
  });

  it("defaults `now` to the current time", () => {
    const longAgo = "2000-01-01T00:00:00.000Z" as IsoTimestamp;
    const farAhead = "2999-01-01T00:00:00.000Z" as IsoTimestamp;

    expect(
      lockReasonFor(makeSubscription({ status: "trialing", currentPeriodEnd: longAgo })),
    ).toBe("trial_ended");
    expect(
      lockReasonFor(makeSubscription({ status: "trialing", currentPeriodEnd: farAhead })),
    ).toBeNull();
  });

  it("carries the org, the reason and the plan-limit code on the error", () => {
    const error = new WorkspaceLockedError(ORG_A, "trial_ended");

    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(error.reason).toBe("trial_ended");
  });
});
