/**
 * A workspace whose subscription is not in good standing is read-only: member
 * writes are refused with `WorkspaceLockedError`, while reads, billing,
 * notification housekeeping and Taskflow's own background work carry on.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { eq } from "drizzle-orm";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { WorkspaceLockedError } from "@/lib/billing-lock";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, subscriptions } from "@/server/db";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as billingService from "@/server/services/billing-service";
import * as commentService from "@/server/services/comment-service";
import * as featureFlagService from "@/server/services/feature-flag-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as labelService from "@/server/services/label-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { SubscriptionRow } from "@/server/db/schema/billing";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

const DAY_MS = 24 * 60 * 60 * 1000;
const YESTERDAY = toIsoTimestamp(new Date(Date.now() - DAY_MS));
const TOMORROW = toIsoTimestamp(new Date(Date.now() + DAY_MS));

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

/** Rewrites the stored subscription — the only thing the lock rule reads. */
function setSubscription(orgId: OrgId, patch: Partial<SubscriptionRow>): void {
  getDb().update(subscriptions).set(patch).where(eq(subscriptions.orgId, orgId)).run();
}

/** Counts every event of the given types published while `run` executes. */
async function countEvents(
  types: readonly (keyof TaskflowEventMap)[],
  run: () => Promise<void>,
): Promise<number> {
  let seen = 0;
  const offs: Unsubscribe[] = types.map((type) =>
    subscribe(type, () => {
      seen += 1;
    }),
  );
  try {
    await run();
  } finally {
    for (const off of offs) off();
  }
  return seen;
}

async function expectLocked(write: Promise<unknown>, reason: string): Promise<void> {
  const error: unknown = await write.then(
    () => null,
    (thrown: unknown) => thrown,
  );
  expect(error).toBeInstanceOf(WorkspaceLockedError);
  expect((error as WorkspaceLockedError).reason).toBe(reason);
}

describe("workspace lock", () => {
  it("lets an in-good-standing workspace write and reports no lock", async () => {
    const tenant = await createTenant("lock-writable", "growth");

    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
    await expect(
      issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id)),
    ).resolves.toMatchObject({ orgId: tenant.org.id });

    const summary = await organizationService.getOrganizationSummary(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(summary.lockReason).toBeNull();
  });

  it("evaluates the stored subscription at the supplied moment", async () => {
    const tenant = await createTenant("lock-moment", "growth");
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    const periodEnd = new Date(subscription!.currentPeriodEnd);

    // A fresh paid tenant is trialing: writable until the period end is reached.
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date(periodEnd.getTime() - 1)),
    ).resolves.toBeUndefined();
    await expectLocked(
      billingService.assertWorkspaceWritable(tenant.org.id, periodEnd),
      "trial_ended",
    );

    // A cancellation scheduled for later only bites once its date arrives.
    setSubscription(tenant.org.id, { status: "canceled", cancelAt: TOMORROW });
    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
    await expectLocked(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date(Date.now() + 2 * DAY_MS)),
      "canceled",
    );

    setSubscription(tenant.org.id, { status: "canceled", cancelAt: null });
    await expectLocked(billingService.assertWorkspaceWritable(tenant.org.id), "canceled");
  });

  it("refuses every content write, writing and publishing nothing", async () => {
    const tenant = await createTenant("lock-content", "growth");
    const { owner, member } = tenant.actors;
    const orgId = tenant.org.id;

    const issue = await issueService.createIssue(member, issueInput(orgId, tenant.project.id));
    const comment = await commentService.createComment(member, {
      orgId,
      issueId: issue.id,
      body: "before the lock",
      parentId: null,
      mentionedUserIds: [],
    });
    const label = await labelService.createLabel(owner, {
      orgId,
      name: "bug",
      color: "#ff0000",
      description: null,
    });

    setSubscription(orgId, { status: "past_due" });

    const published = await countEvents(
      [
        "issue.created",
        "issue.updated",
        "issue.status_changed",
        "issue.assigned",
        "issue.archived",
        "comment.created",
        "comment.deleted",
        "project.created",
        "project.archived",
        "project.restored",
      ],
      async () => {
        await expectLocked(
          issueService.createIssue(member, issueInput(orgId, tenant.project.id)),
          "past_due",
        );
        await expectLocked(
          issueService.updateIssue(member, { orgId, issueId: issue.id, title: "Renamed" }),
          "past_due",
        );
        await expectLocked(
          issueService.changeIssueStatus(member, { orgId, issueId: issue.id, status: "done" }),
          "past_due",
        );
        await expectLocked(
          issueService.moveIssue(member, {
            orgId,
            issueId: issue.id,
            toStatus: "in_progress",
            toIndex: 0,
          }),
          "past_due",
        );
        await expectLocked(
          issueService.assignIssue(member, {
            orgId,
            issueId: issue.id,
            assigneeId: tenant.userIds.admin,
          }),
          "past_due",
        );
        await expectLocked(
          issueService.assignIssue(member, { orgId, issueId: issue.id, assigneeId: null }),
          "past_due",
        );
        await expectLocked(issueService.archiveIssue(member, orgId, issue.id), "past_due");

        await expectLocked(
          commentService.createComment(member, {
            orgId,
            issueId: issue.id,
            body: "after the lock",
            parentId: null,
            mentionedUserIds: [],
          }),
          "past_due",
        );
        await expectLocked(
          commentService.updateComment(member, { orgId, commentId: comment.id, body: "edited" }),
          "past_due",
        );
        await expectLocked(
          commentService.deleteComment(member, { orgId, commentId: comment.id }),
          "past_due",
        );

        await expectLocked(
          projectService.createProject(owner, {
            orgId,
            name: "Second project",
            slug: "second-project",
            key: "SEC",
            description: null,
            visibility: "org",
            leadId: null,
            color: "#6366f1",
            targetDate: null,
          }),
          "past_due",
        );
        await expectLocked(
          projectService.updateProject(owner, {
            orgId,
            projectId: tenant.project.id,
            name: "Renamed project",
          }),
          "past_due",
        );
        await expectLocked(
          projectService.archiveProject(owner, {
            orgId,
            projectId: tenant.project.id,
            archiveIssues: true,
          }),
          "past_due",
        );
        await expectLocked(
          projectService.restoreProject(owner, orgId, tenant.project.id),
          "past_due",
        );

        await expectLocked(
          labelService.createLabel(owner, {
            orgId,
            name: "chore",
            color: "#00ff00",
            description: null,
          }),
          "past_due",
        );
        await expectLocked(labelService.deleteLabel(owner, orgId, label.id), "past_due");
      },
    );

    expect(published).toBe(0);

    // Nothing moved in storage either.
    const stored = await issueRepo.findIssueById(orgId, issue.id);
    expect(stored).toMatchObject({
      title: issue.title,
      status: issue.status,
      assigneeId: null,
      archivedAt: null,
    });
    await expect(issueRepo.countIssues(orgId, tenant.project.id)).resolves.toBe(1);
    await expect(projectRepo.countProjects(orgId)).resolves.toBe(1);
    await expect(labelService.listLabels(member, orgId)).resolves.toHaveLength(1);

    // …and every read still answers.
    const thread = await commentService.getThread(tenant.actors.viewer, orgId, issue.id);
    expect(thread).toHaveLength(1);
    await expect(
      issueService.getIssue(tenant.actors.viewer, orgId, issue.id),
    ).resolves.toMatchObject({ commentCount: 1 });
    await expect(
      organizationService.getOrganizationSummary(tenant.actors.viewer, orgId),
    ).resolves.toMatchObject({ lockReason: "past_due" });
  });

  it("refuses membership, invitation and settings writes", async () => {
    const tenant = await createTenant("lock-admin", "growth");
    const { owner, admin } = tenant.actors;
    const orgId = tenant.org.id;

    const pending = await invitationService.inviteMember(admin, {
      orgId,
      email: "pending@lock-admin.test",
      role: "member",
    });
    const targetMember = await memberRepo.findMember(orgId, tenant.userIds.member);

    setSubscription(orgId, { status: "canceled", cancelAt: YESTERDAY });

    const published = await countEvents(
      ["member.invited", "member.role_changed", "member.removed", "flag.toggled"],
      async () => {
        await expectLocked(
          memberService.updateMemberRole(owner, {
            orgId,
            memberId: targetMember!.id,
            role: "admin",
          }),
          "canceled",
        );
        await expectLocked(
          memberService.removeMember(owner, { orgId, memberId: targetMember!.id }),
          "canceled",
        );
        await expectLocked(
          invitationService.inviteMember(admin, {
            orgId,
            email: "late@lock-admin.test",
            role: "member",
          }),
          "canceled",
        );
        await expectLocked(invitationService.revokeInvitation(admin, pending.id), "canceled");
        await expectLocked(invitationService.resendInvitation(admin, pending.id), "canceled");
        await expectLocked(
          organizationService.updateOrganization(owner, { orgId, name: "Renamed inc" }),
          "canceled",
        );
        await expectLocked(
          featureFlagService.toggleFlag(owner, { orgId, flag: "kanban_board", enabled: true }),
          "canceled",
        );
        await expectLocked(
          webhookService.createWebhook(owner, {
            orgId,
            url: "https://hooks.lock-admin.test/in",
            eventTypes: ["issue.created"],
          }),
          "canceled",
        );
      },
    );

    expect(published).toBe(0);
    await expect(memberRepo.findMember(orgId, tenant.userIds.member)).resolves.toMatchObject({
      role: "member",
      archivedAt: null,
    });
    const stillPending = await invitationRepo.listPendingInvitations(orgId);
    expect(stillPending.map((row) => row.id)).toEqual([pending.id]);
    await expect(orgRepo.findOrgById(orgId)).resolves.toMatchObject({ name: tenant.org.name });
    await expect(webhookService.listWebhooks(owner, orgId)).resolves.toHaveLength(0);
  });

  it("keeps an invitation into a locked workspace pending", async () => {
    const tenant = await createTenant("lock-accept", "growth");
    const orgId = tenant.org.id;
    const token = "d".repeat(32);

    await invitationRepo.insertInvitation(
      orgId,
      { orgId, email: "joiner@lock-accept.test", role: "member", expiresInDays: 7 },
      tenant.userIds.admin,
      hashToken(token),
    );
    const joiner = await userRepo.insertUser({
