  it("unlocks an ended trial that fits the free plan and leaves the rest locked", async () => {
    // createTenant seeds four members; the free plan has three seats.
    const tooBig = await createTenant("lock-trial-big", "growth");
    await usageRepo.recomputeUsage(tooBig.org.id);

    const fits = await createTenant("lock-trial-fits", "growth");
    const viewer = await memberRepo.findMember(fits.org.id, fits.userIds.viewer);
    await memberRepo.archiveMember(fits.org.id, viewer!.id);
    await usageRepo.recomputeUsage(fits.org.id);

    for (const orgId of [tooBig.org.id, fits.org.id]) {
      setSubscription(orgId, { status: "trialing", currentPeriodEnd: YESTERDAY });
      await expectLocked(billingService.assertWorkspaceWritable(orgId), "trial_ended");
    }

    await runTrialExpiryJob(new Date());

    await expect(subscriptionRepo.findSubscription(fits.org.id)).resolves.toMatchObject({
      plan: "free",
      status: "active",
    });
    await expect(billingService.assertWorkspaceWritable(fits.org.id)).resolves.toBeUndefined();

    await expectLocked(billingService.assertWorkspaceWritable(tooBig.org.id), "trial_ended");
    await billingService.changePlan(tooBig.actors.owner, {
      orgId: tooBig.org.id,
      plan: "growth",
      interval: "monthly",
    });
    await expect(billingService.assertWorkspaceWritable(tooBig.org.id)).resolves.toBeUndefined();
  });
});
